# ORIGINAL: F1b's gate (lk-channel evidence/r2/design/flags_rest.md D3-D6, §6) — set_prolog_flag/2, create_prolog_flag/3 and the flag side effects
# (pl-prologflag.c set_flag_value, set_prolog_flag_unlocked, create_prolog_flag), against swipl 10.1.19; the rows are generated by evidence/F1B/.
# test/core_lang/test_set_flag_swipl.jl — pl-prologflag.c's WRITE side: `check_flag_write_access`, `check_create_flag`, `keep_flag`,
# `new_prolog_flag`, `set_flag_value` per flag type (`FT_BOOL`, `FT_ATOM`, `FT_INTEGER`, `FT_FLOAT`, `FT_TERM`) and the module flags
# (`setDoubleQuotes`, `setBackQuotes`, `setRationalSyntax`, `setVarPrefix`, `setUnknown`), `setOccursCheck`, `setWriteAttributes`,
# `setStreamTypeCheck`, `setAccessLevelFromAtom`, `checkOnError`, the mask writes (`setPrologFlagMask!`) that the compiler, the VM and
# the arithmetic read (D3), and the rows of D-0280 item 5: `protected_predicate` once `iso` and `protect_static_code` are settable
# (rows sf80-sf89 are the kill rows of D1-95 and D1-96 of tools/mutants/D1c.py, and of F1B.py).
#   * A PROGRAM consulted by the kernel's loader, and cases `t_<id>(R)` run IN ORDER in one database, each wrapped in
#     `catch(Goal, error(E, _), R = raised(E))`; a case restores the flags it changes, but sf85-sf89 end with `protect_static_code`
#     true: it cannot be set false again (swipl's answer), so they come last.
#   * Every answer line is swipl's, PINNED (swipl 10.1.19-1-gcbf4e189, evidence/F1B/gen_sf_rows.py, two runs byte-identical); with
#     `swipl` on PATH the live answers are compared with the pins too.
#   * The flags whose upstream side effect lives in a file the kernel has not ported are REFUSED BY NAME (design D4, `NotPortedError`):
#     the last testset pins that list. swipl 10.1.19 does not answer `set_prolog_flag(user_flags, error)` followed by a new key: that case is
#     in no row, and the kernel's answer (existence_error(prolog_flag, K)) is pinned below with this comment.
using Test, LogicKernel
const LK = LogicKernel

# TERM TYPES PER CHUNK: REFERENCE — the flag write side (src/os/pl-prologflag.jl), built on the term layer; every type in CI and at milestones
include(joinpath(@__DIR__, "..", "term_under_test.jl"))
const _SF = lk_term_type(Union{Int64, Float64, String, BigInt, Rational{BigInt}})
_sfs(x) = lk_sym(_SF, Symbol(x))

_sf_codes(s::String) = "[" * join(Int.(collect(s)), ",") * "]"
"A term as the driver's `enc/1` writes it: `V<i>` by first occurrence, atoms and functors by their codes."
function _sf_enc(t::_SF, seen::Vector{UInt64}=UInt64[])::String
    k = kind(t)
    if k === VAR
        i = findfirst(==(var_key(t)), seen)
        if i === nothing
            push!(seen, var_key(t))
            i = length(seen)
        end
        return "V$(i - 1)"
    elseif k === SYM
        return is_nil(t) ? "nil" : "a" * _sf_codes(sym_text(t))
    elseif k === GND
        v = lk_value(t)
        v isa AbstractString && return "s" * _sf_codes(String(v))
        v isa Integer && return "i$v"
        v isa Rational && return "q$(numerator(v))r$(denominator(v))"
        v isa AbstractFloat && return "f$(v)"
        return "?$(typeof(v))"
    end
    h = child(t, 1)
    return (is_nil(h) ? "c[]" : "c" * _sf_codes(sym_text(h))) * "/$(nchildren(t) - 1)(" *
           join([_sf_enc(child(t, i), seen) for i in 2:nchildren(t)], ",") * ")"
end

# the swipl side: the driver of test_at_body_swipl.jl (consult, then every answer of each t_<id>/1, `enc`oded)
const _SF_DRIVER = raw"""
enc(T) :- enc(T, [], _).
enc(V, S0, S) :- var(V), !, ( vidx(S0, V, 0, I) -> S = S0 ; length(S0, I), append(S0, [V], S) ), format("V~w", [I]).
enc(T, S, S) :- T == [], !, write(nil).
enc(T, S, S) :- atom(T), !, atom_codes(T, Cs), format("a~w", [Cs]).
enc(T, S, S) :- string(T), !, string_codes(T, Cs), format("s~w", [Cs]).
enc(T, S, S) :- integer(T), !, format("i~w", [T]).
enc(T, S, S) :- rational(T, N, D), !, format("q~wr~w", [N, D]).
enc(T, S, S) :- float(T), !, format("f~w", [T]).
enc(T, S0, S) :- compound_name_arity(T, N, A),
    ( N == [] -> write('c[]') ; atom_codes(N, Cs), format("c~w", [Cs]) ),
    format("/~w(", [A]), encargs(1, A, T, S0, S), write(')').
encargs(I, A, _, S, S) :- I > A, !.
encargs(I, A, T, S0, S) :- arg(I, T, X), enc(X, S0, S1), ( I < A -> write(',') ; true ),
    I1 is I+1, encargs(I1, A, T, S1, S).
vidx([X|_], V, I, I) :- X == V, !.
vidx([_|Xs], V, I0, I) :- I1 is I0+1, vidx(Xs, V, I1, I).
fz_pred(N) :-
    format("~w", [N]), functor(G, N, 1),
    catch(findnsols(50, G, G, Gs), _, Gs = [exception]),
    forall(member(S, Gs), ( S == exception -> write(' exception') ; write(' '), enc(S) )), nl.
fz_run(File, Ns) :-
    catch(( consult(File), S = ok ), E, S = exc(E)),
    ( S == ok -> writeln(ok) ; S = exc(B), write('exc '), enc(B), nl ),
    forall(member(N, Ns), fz_pred(N)).
"""
function _sf_swipl_lines(path::String, names::Vector{String})::Vector{String}
    out = mktempdir() do d
        f = joinpath(d, "drv.pl")
        write(
            f,
            _SF_DRIVER * ":- initialization((fz_run('$path', [" * join(names, ",") *
            "]), halt)).\n"
        )
        read(pipeline(`swipl -q $f`; stdin=devnull, stderr=devnull), String)
    end
    return String.(split(chomp(out), '\n'; keepempty=false))
end

# the program: the predicates the rows read clauses of (sp/1 static, sd/1 dynamic, ssd/1 dynamic with an SSU clause added by a row)
const _SF_PROGRAM = raw"""
:- dynamic sd/1.
:- dynamic ssd/1.
sd(1).
sp(1).
sp(2).
"""

# (id, goal), run IN ORDER
const _SF_CASES = [
@@CASES@@]

# swipl 10.1.19-1-gcbf4e189's answers to the program and cases above (the driver's lines; evidence/F1B/sf_rows.out)
const _SF_PINNED = [
# PINS-BEGIN
# PINS-END
]

"The program and cases as one file; the case predicates' names."
function _sf_file()::Tuple{String, Vector{String}}
    names = ["t_$(id)" for (id, _) in _SF_CASES]
    text =
        _SF_PROGRAM * join([
            "t_$(id)(R) :- catch(($g), error(SfE, _), R = raised(SfE)).\n" for
            (id, g) in _SF_CASES
        ])
    f = joinpath(mktempdir(), "setflag.pl")
    write(f, text)
    return f, names
end

"The kernel's answers to the query `name(R)` in `gd`: the encoded lines, at most 50 answers; a Julia exception propagates."
function _sf_query(gd, ld, name::String)::String
    proc = LK.isCurrentProcedure(sym_key(_sfs(name)), 1, LK.MODULE_user(gd))
    if proc === nothing || !LK.isDefinedProcedure(gd, proc)
        return "$name undefined"
    end
    sols = String[]
    fid = LK.PL_open_foreign_frame(ld)
    a = LK.PL_new_term_refs(ld, 1)
    LK.putSlotValue!(ld, a + 1, mk_var(_SF, LK.fresh_var_keys!(1)), LK.PutVarMap())
    qid = LK.PL_open_query(
        gd, ld, nothing, LK.PL_Q_CATCH_EXCEPTION | LK.PL_Q_EXT_STATUS, proc, a
    )
    n = 0
    try
        while (n += 1) <= 50
            rc = LK.PL_next_solution(gd, ld, qid)
            if rc == LK.PL_S_TRUE || rc == LK.PL_S_LAST
                push!(
                    sols,
                    _sf_enc(mk_expr(_SF, _SF[_sfs(name), lk_answers(ld, (a:a)...)...]))
                )
                rc == LK.PL_S_LAST && break
            elseif rc == LK.PL_S_EXCEPTION
                push!(sols, "exception")
                break
            else
                break
            end
        end
    finally
        LK.PL_close_query(ld, qid)
        LK.PL_close_foreign_frame(ld, fid)
    end
    return "$name" * join(" " .* sols)
end

"The kernel's lines for `names` after consulting `path`, as the driver writes swipl's; the database and the local data."
function _sf_kernel(path::String, names::Vector{String})
    gd = LK.PL_global_data{_SF}()
    ld = LK.PL_local_data{_SF}(gd)
    st, ball, _ = LK.load_file!(gd, ld, path)
    out = [st === :ok ? "ok" : "exc " * _sf_enc(ball::_SF)]
    for name in names
        push!(out, _sf_query(gd, ld, name))
    end
    return out, gd, ld
end

@testset "set_prolog_flag/2, create_prolog_flag/3 and the flag side effects as swipl's (sf01-sf89)" begin
    f, names = _sf_file()
    kl, _, _ = _sf_kernel(f, names)
    @test length(kl) == length(_SF_PINNED)
    for (k, p) in zip(kl, _SF_PINNED)
        k == p || println(stderr, "  ours  ", k, "\n  swipl ", p)
        @test k == p
    end
    # not vacuous: the pins hold both kinds of answer — a raised error (permission, type, domain, instantiation) and a value read back
    raised = "c[114,97,105,115,101,100]"                 # raised(…)
    @test count(l -> occursin(raised, l), _SF_PINNED) >= 30
    @test count(l -> !occursin(raised, l) && startswith(l, "t_"), _SF_PINNED) >= 30
    @test any(l -> startswith(l, "t_sf01 ") && occursin("c[112,101,114,109,105,115,115,105,111,110,95,101,114,114,111,114]/3(", l), _SF_PINNED)
end

@testset "the pins are swipl's (live, when swipl is on PATH)" begin
    swipl = get(ENV, "LOGICKERNEL_NO_SWIPL", "") == "1" ? nothing : Sys.which("swipl")
    # the pinned table is the driver's whole output (the inert-testset guard: an assertion either way)
    @test length(_SF_PINNED) == length(_SF_CASES) + 1
    if swipl === nothing
        @info "F1b LIVE CHECK NOT RUN: `swipl` is not on PATH here. It runs in tools/run_tests.sh and CI."
    else
        f, names = _sf_file()
        @test _sf_swipl_lines(f, names) == _SF_PINNED
    end
end

# the flags refused BY NAME (design D4): the flag is DEFINED at upstream's default and setting it raises `NotPortedError` naming the
# side effect that lives in a file not yet ported; a value the flag accepts is given, so the refusal is the answer, not a type error
# Values swipl 10.1.19 accepts for the flag (probed); the kernel checks oneof and read-only BEFORE it refuses, so a
# value outside the flag's domain would end in a different error. `file_name_case_handling` is READ-ONLY (swipl and the
# kernel answer permission_error(modify, flag, file_name_case_handling)): it has no row here.
const _SF_REFUSED = [
    ("debug", "true"), ("debugger_show_context", "true"),
    ("tty_control", "true"), ("debug_on_interrupt", "true"), ("var_tag", "dict"),
    ("incomparable", "error"), ("encoding", "utf8"), ("unicode_atoms", "error"),
    ("autoload", "false"), ("table_monotonic", "lazy"),
    ("theme", "dark"), ("agc_margin", "100"), ("table_space", "1000000"),
    ("table_compile_threshold", "5"), ("table_drop_intermediate", "5"), ("stack_limit", "1000000000"),
    ("heartbeat", "0"),
    ("float_overflow", "infinity"), ("max_answers_for_subgoal", "5"), ("max_table_subgoal_size", "5")
]

@testset "the flags refused by name raise NotPortedError (design D4)" begin
    text = join(["r_$(f)(R) :- set_prolog_flag($f, $v), R = ok.\n" for (f, v) in _SF_REFUSED])
    path = joinpath(mktempdir(), "refused.pl")
    write(path, text)
    for (f, _) in _SF_REFUSED
        gd = LK.PL_global_data{_SF}()
        ld = LK.PL_local_data{_SF}(gd)
        st, _, _ = LK.load_file!(gd, ld, path)
        @test st === :ok
        # UNVERIFIED on the kernel: gate decides (the refusal's class for `threads`, `tty_control`: the value that changes the flag)
        @test_throws LK.NotPortedError _sf_query(gd, ld, "r_$(f)")
    end
    @test length(_SF_REFUSED) >= 20
end

# the kernel's answer where swipl 10.1.19 does not answer: `set_prolog_flag(user_flags, error)`, then a new key — the
# kernel raises existence_error(prolog_flag, K) at once (pl-prologflag.c check_create_flag)
@testset "user_flags=error and a new key: the kernel's answer (swipl 10.1.19 does not answer this case)" begin
    path = joinpath(mktempdir(), "uferr.pl")
    write(
        path,
        "t_uf(R) :- set_prolog_flag(user_flags, error), catch(set_prolog_flag(zz_uf_new, 1), error(E, _), true), set_prolog_flag(user_flags, silent), R = E.\n"
    )
    gd = LK.PL_global_data{_SF}()
    ld = LK.PL_local_data{_SF}(gd)
    LK.load_file!(gd, ld, path)
    line = _sf_query(gd, ld, "t_uf")
    ek = _sf_codes("existence_error")
    @test occursin("c" * ek * "/2(a" * _sf_codes("prolog_flag") * ",a" * _sf_codes("zz_uf_new") * ")", line)
end
